-- Reviewed course tuition percentage creates gross accounting only.
-- Session allocations and collected-receipt bases have separate source ownership.
CREATE TABLE public.payroll_tuition_course_accruals(
 academy_id uuid NOT NULL,id uuid NOT NULL,engagement_id uuid NOT NULL,work_version integer NOT NULL,terms_version integer NOT NULL,person_id uuid NOT NULL,hub_id uuid,
 component_code text NOT NULL,invoice_id uuid NOT NULL,plan_id uuid NOT NULL,basis text NOT NULL CHECK(basis IN('course_net','course_gross')),
 earned_on date NOT NULL,due_on date NOT NULL,posted_on date NOT NULL,currency_id uuid NOT NULL,currency_version integer NOT NULL,unit_scale integer NOT NULL CHECK(unit_scale BETWEEN 0 AND 18),amount_minor numeric NOT NULL CHECK(amount_minor>0 AND amount_minor=trunc(amount_minor) AND amount_minor<1e38),
 expense_account uuid NOT NULL,expense_version integer NOT NULL,liability_account uuid NOT NULL,liability_version integer NOT NULL,period_id uuid NOT NULL,period_version integer NOT NULL,
 input jsonb NOT NULL,source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object' AND octet_length(source_snapshot::text)<=131072),approval_id uuid NOT NULL,created_by uuid NOT NULL,void_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),CHECK(earned_on BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' AND due_on BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' AND posted_on BETWEEN earned_on AND DATE '9999-12-31'),
 FOREIGN KEY(academy_id,invoice_id) REFERENCES public.tuition_invoices(academy_id,id),FOREIGN KEY(academy_id,engagement_id,terms_version) REFERENCES public.work_engagement_revisions(academy_id,engagement_id,version),FOREIGN KEY(academy_id,person_id) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,hub_id) REFERENCES public.hubs(academy_id,id),
 FOREIGN KEY(academy_id,currency_id,currency_version) REFERENCES public.finance_currency_revisions(academy_id,currency_id,version),FOREIGN KEY(academy_id,expense_account,expense_version) REFERENCES public.finance_account_revisions(academy_id,account_id,version),FOREIGN KEY(academy_id,liability_account,liability_version) REFERENCES public.finance_account_revisions(academy_id,account_id,version),FOREIGN KEY(academy_id,period_id,period_version) REFERENCES public.finance_period_revisions(academy_id,period_id,version),
 FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
-- Identity is independent of component label, terms version, quantity and date.
ALTER TABLE public.payroll_tuition_course_accruals ADD CONSTRAINT tuition_course_plan FOREIGN KEY(academy_id,plan_id) REFERENCES public.tuition_plans(academy_id,id);
CREATE UNIQUE INDEX tuition_course_live_delivery ON public.payroll_tuition_course_accruals(academy_id,engagement_id,plan_id) WHERE void_id IS NULL;
CREATE INDEX tuition_course_delivery_history ON public.payroll_tuition_course_accruals(academy_id,engagement_id,plan_id);
CREATE INDEX tuition_course_worker_due ON public.payroll_tuition_course_accruals(academy_id,person_id,due_on,id);
CREATE TABLE public.payroll_tuition_course_voids(
 academy_id uuid NOT NULL,id uuid NOT NULL,accrual_id uuid NOT NULL,input jsonb NOT NULL,source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object' AND octet_length(source_snapshot::text)<=131072),approval_id uuid NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,accrual_id),UNIQUE(academy_id,id,accrual_id),FOREIGN KEY(academy_id,accrual_id) REFERENCES public.payroll_tuition_course_accruals(academy_id,id),FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
ALTER TABLE public.payroll_tuition_course_accruals ADD CONSTRAINT tuition_course_void_identity FOREIGN KEY(academy_id,void_id,id) REFERENCES public.payroll_tuition_course_voids(academy_id,id,accrual_id) DEFERRABLE INITIALLY DEFERRED;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['payroll_tuition_course_accruals','payroll_tuition_course_voids'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_boundary ON public.%I USING(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid) WITH CHECK(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid)',t);
 EXECUTE format('CREATE TRIGGER tuition_course_write BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION public.guard_expense_commitment_write()',t);
 EXECUTE format('GRANT SELECT ON public.%I TO kavosh_runtime',t);
END LOOP;END $$;
-- All searchable financial metadata is derived by the guarded trigger, not
-- supplied by the application or an INSERT with a caller-chosen amount.
GRANT INSERT(academy_id,id,input,source_snapshot,approval_id,created_by) ON public.payroll_tuition_course_accruals TO kavosh_runtime;
GRANT UPDATE(void_id) ON public.payroll_tuition_course_accruals TO kavosh_runtime;
GRANT INSERT(academy_id,id,accrual_id,input,source_snapshot,approval_id,created_by) ON public.payroll_tuition_course_voids TO kavosh_runtime;

CREATE FUNCTION public.tuition_course_input_valid(i jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE k text;r jsonb;d date;keys text[]:=ARRAY['engagement','termsVersion','componentCode','invoiceId','earnedOn','dueOn','postedOn','period','expenseAccount','liabilityAccount','earningReview','taxReview','reason'];BEGIN
 IF jsonb_typeof(i) IS DISTINCT FROM 'object' OR NOT(i ?& keys) OR i-keys<>'{}'::jsonb OR octet_length(i::text)>65536 THEN RETURN false;END IF;
 FOREACH k IN ARRAY ARRAY['earningReview','taxReview','reason'] LOOP IF jsonb_typeof(i->k) IS DISTINCT FROM 'string' OR length(btrim(i->>k)) NOT BETWEEN 1 AND 2000 THEN RETURN false;END IF;END LOOP;
 IF jsonb_typeof(i->'componentCode') IS DISTINCT FROM 'string' OR i->>'componentCode'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$' OR jsonb_typeof(i->'invoiceId') IS DISTINCT FROM 'string' OR(i->>'invoiceId')::uuid::text IS DISTINCT FROM i->>'invoiceId' THEN RETURN false;END IF;
 FOREACH k IN ARRAY ARRAY['engagement','period','expenseAccount','liabilityAccount'] LOOP r=i->k;IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR NOT(r ?& ARRAY['id','version']) OR r-ARRAY['id','version']<>'{}'::jsonb OR jsonb_typeof(r->'id') IS DISTINCT FROM 'string' OR(r->>'id')::uuid::text IS DISTINCT FROM r->>'id' OR jsonb_typeof(r->'version') IS DISTINCT FROM 'number' OR(r->>'version')::numeric NOT BETWEEN 1 AND 2147483647 OR(r->>'version')::numeric<>trunc((r->>'version')::numeric) THEN RETURN false;END IF;END LOOP;
 IF jsonb_typeof(i->'termsVersion') IS DISTINCT FROM 'number' OR(i->>'termsVersion')::numeric NOT BETWEEN 1 AND 2147483647 OR(i->>'termsVersion')::numeric<>trunc((i->>'termsVersion')::numeric) THEN RETURN false;END IF;
 FOREACH k IN ARRAY ARRAY['earnedOn','dueOn','postedOn'] LOOP IF jsonb_typeof(i->k) IS DISTINCT FROM 'string' OR i->>k!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RETURN false;END IF;d=(i->>k)::date;IF d NOT BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' THEN RETURN false;END IF;END LOOP;
 RETURN(i->>'postedOn')::date>=(i->>'earnedOn')::date;
 EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN RETURN false;
END $$;
CREATE FUNCTION public.tuition_course_accrual_source(i jsonb,p_exclude uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ DECLARE tenant uuid:=nullif(current_setting('app.academy_id',true),'')::uuid;s jsonb;w jsonb;c jsonb;r record;t record;a record;floor_on date;BEGIN
 s=public.payroll_adjustment_source((i#>>'{engagement,id}')::uuid,(i->>'earnedOn')::date,(i#>>'{expenseAccount,id}')::uuid,(i#>>'{liabilityAccount,id}')::uuid,(i#>>'{period,id}')::uuid);IF s IS NULL THEN RETURN NULL;END IF;w=s->'work';
 IF(w->>'headerVersion')::integer<>(i#>>'{engagement,version}')::integer OR(w->>'termsVersion')::integer<>(i->>'termsVersion')::integer THEN RETURN jsonb_build_object('unavailable','WORK_TERMS_CHANGED');END IF;
 IF w->'active'<>'true'::jsonb OR w->>'classification' NOT IN('employee','contractor') OR(i->>'earnedOn')::date<(w->>'startsOn')::date OR(w->>'endsOn' IS NOT NULL AND(i->>'earnedOn')::date>(w->>'endsOn')::date) THEN RETURN jsonb_build_object('unavailable','EFFECTIVE_COMPENSATED_WORK_REQUIRED');END IF;
 SELECT * INTO r FROM public.work_engagement_revisions WHERE academy_id=tenant AND engagement_id=(w->>'id')::uuid AND version=(w->>'termsVersion')::integer;
 SELECT value INTO c FROM jsonb_array_elements(r.components) WHERE value->>'code'=i->>'componentCode' AND value->>'kind'='tuition_percentage' AND(i->>'earnedOn')::date>=(value->>'from')::date AND(value->>'through' IS NULL OR(i->>'earnedOn')::date<=(value->>'through')::date);
 IF c IS NULL OR c->>'basis' NOT IN('course_net','course_gross') THEN RETURN jsonb_build_object('unavailable','COURSE_PERCENTAGE_COMPONENT_REQUIRED');END IF;
 SELECT x.id,x.plan_id,x.plan_version,x.student_id,x.class_id,x.hub_id,x.credit_id,d.issued_on,p.currency_id,p.unit_scale,v.net_minor,v.gross_minor,v.supply_on INTO t FROM public.tuition_invoices x JOIN public.billing_documents d ON d.academy_id=x.academy_id AND d.id=x.id JOIN public.tuition_plans p ON p.academy_id=x.academy_id AND p.id=x.plan_id JOIN public.tuition_plan_revisions v ON v.academy_id=x.academy_id AND v.plan_id=x.plan_id AND v.version=x.plan_version WHERE x.academy_id=tenant AND x.id=(i->>'invoiceId')::uuid;
 IF t.id IS NULL THEN RETURN NULL;END IF;
 IF t.credit_id IS NOT NULL THEN RETURN jsonb_build_object('unavailable','CREDITED_TUITION_SOURCE_REQUIRES_REVIEW');END IF;
 IF t.currency_id::text<>w->>'currencyId' OR t.hub_id IS DISTINCT FROM(w->>'hubId')::uuid OR(i->>'earnedOn')::date<t.issued_on THEN RETURN jsonb_build_object('unavailable','TUITION_COURSE_SOURCE_MISMATCH');END IF;
 SELECT x.id,x.class_id,x.person_id,v.version,v.definition INTO a FROM public.class_staff x JOIN public.class_staff_revisions v ON v.academy_id=x.academy_id AND v.assignment_id=x.id AND v.version=(c#>>'{assignment,version}')::integer WHERE x.academy_id=tenant AND x.id=(c#>>'{assignment,id}')::uuid;
 IF a.id IS NULL OR a.class_id IS DISTINCT FROM t.class_id OR a.person_id::text IS DISTINCT FROM w->>'personId' OR a.definition->'active' IS DISTINCT FROM 'true'::jsonb OR(i->>'earnedOn')::date<(a.definition->>'startsOn')::date OR(a.definition->>'endsOn' IS NOT NULL AND(i->>'earnedOn')::date>(a.definition->>'endsOn')::date) THEN RETURN jsonb_build_object('unavailable','TUITION_COURSE_ASSIGNMENT_REQUIRED');END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_course_accruals x WHERE x.academy_id=tenant AND x.engagement_id=(w->>'id')::uuid AND x.plan_id=t.plan_id AND x.void_id IS NULL AND(p_exclude IS NULL OR x.id<>p_exclude)) THEN RETURN jsonb_build_object('unavailable','TUITION_COURSE_ALREADY_ACCRUED');END IF;
 SELECT max(j.posted_on) INTO floor_on FROM public.payroll_tuition_course_accruals x JOIN public.finance_journals j ON j.academy_id=x.academy_id AND j.id=x.void_id WHERE x.academy_id=tenant AND x.engagement_id=(w->>'id')::uuid AND x.plan_id=t.plan_id AND x.void_id IS NOT NULL AND(p_exclude IS NULL OR x.id<>p_exclude);
 RETURN jsonb_build_object('work',w,'accounting',s-'work','component',c,'tuition',jsonb_build_object('invoiceId',t.id,'planId',t.plan_id,'planVersion',t.plan_version,'studentId',t.student_id,'classId',t.class_id,'hubId',t.hub_id,'currencyId',t.currency_id,'unitScale',t.unit_scale,'netMinor',t.net_minor::text,'grossMinor',t.gross_minor::text,'issuedOn',t.issued_on::text,'supplyOn',t.supply_on::text,'assignmentId',a.id,'assignmentVersion',a.version,'assignment',a.definition),'grossMinor',round((CASE WHEN c->>'basis'='course_net' THEN t.net_minor ELSE t.gross_minor END)*power(10::numeric,(w->>'unitScale')::integer-t.unit_scale)*(c->>'percent')::numeric/100)::text,'releaseFloorOn',floor_on::text);
END $$;
CREATE FUNCTION public.tuition_course_void_source(p_id uuid,p_period uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ DECLARE tenant uuid:=nullif(current_setting('app.academy_id',true),'')::uuid;b record;s jsonb;BEGIN
 SELECT * INTO b FROM public.payroll_tuition_course_accruals WHERE academy_id=tenant AND id=p_id;IF NOT FOUND THEN RETURN NULL;END IF;PERFORM public.lock_pay_period_work(b.engagement_id);SELECT * INTO b FROM public.payroll_tuition_course_accruals WHERE academy_id=tenant AND id=p_id FOR UPDATE;
 s=public.payroll_adjustment_source(b.engagement_id,b.earned_on,b.expense_account,b.liability_account,p_period);IF s IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('before',jsonb_build_object('id',b.id,'engagementId',b.engagement_id,'personId',b.person_id,'hubId',b.hub_id,'voidId',b.void_id,'postedOn',b.posted_on::text),'current',s);
END $$;
CREATE FUNCTION public.tuition_course_record_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;s jsonb;w jsonb;target jsonb;e jsonb;l jsonb;a jsonb;BEGIN
 IF TG_OP='UPDATE' THEN IF OLD.void_id IS NOT NULL OR NEW.void_id IS NULL OR to_jsonb(NEW)-'void_id' IS DISTINCT FROM to_jsonb(OLD)-'void_id' THEN RAISE EXCEPTION 'TUITION_COURSE_ACCRUAL_IMMUTABLE' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 IF NOT public.tuition_course_input_valid(NEW.input) THEN RAISE EXCEPTION 'TUITION_COURSE_INPUT_INVALID' USING ERRCODE='23514';END IF;
 s=public.tuition_course_accrual_source(NEW.input,NEW.id);w=s->'work';SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 target=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',w->>'personId','hubId',w->'hubId')),'workContext',jsonb_build_object('personId',w->>'personId','hubId',w->'hubId'));
 IF s IS NULL OR s ? 'unavailable' OR p.id IS NULL OR p.status<>'pending' OR p.action IS DISTINCT FROM 'work.tuition_course.record' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version IS DISTINCT FROM 0 OR p.privacy_capability IS DISTINCT FROM 'payroll-accruals.view' OR p.scope IS DISTINCT FROM target OR p.payload IS DISTINCT FROM NEW.input OR p.review_context IS DISTINCT FROM s OR NEW.source_snapshot IS DISTINCT FROM s OR NOT public.report_comment_human_verified(NEW.created_by) THEN RAISE EXCEPTION 'TUITION_COURSE_EXACT_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;
 IF NEW.created_by=(w->>'personId')::uuid AND NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) THEN RAISE EXCEPTION 'BENEFICIARY_REVIEW_FORBIDDEN' USING ERRCODE='23514';END IF;
 IF s->>'releaseFloorOn' IS NOT NULL AND(NEW.input->>'postedOn')::date<(s->>'releaseFloorOn')::date THEN RAISE EXCEPTION 'TUITION_COURSE_CORRECTION_DATE_REQUIRED' USING ERRCODE='23514';END IF;
 NEW.engagement_id=(w->>'id')::uuid;NEW.work_version=(w->>'headerVersion')::integer;NEW.terms_version=(w->>'termsVersion')::integer;NEW.person_id=(w->>'personId')::uuid;NEW.hub_id=(w->>'hubId')::uuid;NEW.component_code=NEW.input->>'componentCode';NEW.invoice_id=(NEW.input->>'invoiceId')::uuid;NEW.plan_id=(s#>>'{tuition,planId}')::uuid;NEW.basis=s#>>'{component,basis}';NEW.earned_on=(NEW.input->>'earnedOn')::date;NEW.due_on=(NEW.input->>'dueOn')::date;NEW.posted_on=(NEW.input->>'postedOn')::date;
 NEW.currency_id=(w->>'currencyId')::uuid;NEW.currency_version=(w->>'currencyVersion')::integer;NEW.unit_scale=(w->>'unitScale')::integer;NEW.amount_minor=(s->>'grossMinor')::numeric;NEW.expense_account=(NEW.input#>>'{expenseAccount,id}')::uuid;NEW.expense_version=(NEW.input#>>'{expenseAccount,version}')::integer;NEW.liability_account=(NEW.input#>>'{liabilityAccount,id}')::uuid;NEW.liability_version=(NEW.input#>>'{liabilityAccount,version}')::integer;NEW.period_id=(NEW.input#>>'{period,id}')::uuid;NEW.period_version=(NEW.input#>>'{period,version}')::integer;NEW.created_at=clock_timestamp();
 SELECT value INTO e FROM jsonb_array_elements(s#>'{accounting,accounts}') WHERE value->>'id'=NEW.expense_account::text;SELECT value INTO l FROM jsonb_array_elements(s#>'{accounting,accounts}') WHERE value->>'id'=NEW.liability_account::text;a=s#>'{accounting,period}';
 IF e IS NULL OR l IS NULL OR e->>'kind'<>'expense' OR e->>'role'<>'expense' OR l->>'kind'<>'liability' OR l->>'role'<>'payable' OR e->'active'<>'true'::jsonb OR l->'active'<>'true'::jsonb OR(e->>'version')::integer<>NEW.expense_version OR(l->>'version')::integer<>NEW.liability_version OR e->>'currencyId'<>NEW.currency_id::text OR l->>'currencyId'<>NEW.currency_id::text OR(e->>'unitScale')::integer<>NEW.unit_scale OR(l->>'unitScale')::integer<>NEW.unit_scale OR(e->>'hubId' IS NOT NULL AND(e->>'hubId')::uuid IS DISTINCT FROM NEW.hub_id) OR(l->>'hubId' IS NOT NULL AND(l->>'hubId')::uuid IS DISTINCT FROM NEW.hub_id) OR(a->>'version')::integer<>NEW.period_version OR a->>'state'<>'open' OR NEW.posted_on NOT BETWEEN(a->>'startsOn')::date AND(a->>'endsOn')::date OR(a->>'closedThrough' IS NOT NULL AND NEW.posted_on<=(a->>'closedThrough')::date) THEN RAISE EXCEPTION 'TUITION_COURSE_MAPPING_INVALID' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER tuition_course_record_guard BEFORE INSERT OR UPDATE ON public.payroll_tuition_course_accruals FOR EACH ROW EXECUTE FUNCTION public.tuition_course_record_guard();
CREATE FUNCTION public.tuition_course_void_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;s jsonb;w jsonb;target jsonb;BEGIN
 -- The retained gross-correction body is shared with salary corrections.
 IF NOT public.salary_input_valid(NEW.input,true) OR(NEW.input->>'accrualId')::uuid IS DISTINCT FROM NEW.accrual_id THEN RAISE EXCEPTION 'TUITION_COURSE_INPUT_INVALID' USING ERRCODE='23514';END IF;
 s=public.tuition_course_void_source(NEW.accrual_id,(NEW.input#>>'{period,id}')::uuid);w=s#>'{current,work}';SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 target=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',w->>'personId','hubId',w->'hubId')),'workContext',jsonb_build_object('personId',w->>'personId','hubId',w->'hubId'));
 IF s IS NULL OR p.id IS NULL OR p.status<>'pending' OR p.action IS DISTINCT FROM 'work.tuition_course.void' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version IS DISTINCT FROM 0 OR p.privacy_capability IS DISTINCT FROM 'payroll-accruals.view' OR p.scope IS DISTINCT FROM target OR p.payload IS DISTINCT FROM NEW.input OR p.review_context IS DISTINCT FROM s OR NEW.source_snapshot IS DISTINCT FROM s OR s#>>'{before,voidId}' IS NOT NULL OR NOT public.report_comment_human_verified(NEW.created_by) OR(NEW.input#>>'{period,version}')::integer IS DISTINCT FROM(s#>>'{current,period,version}')::integer OR(NEW.input->>'postedOn')::date<(s#>>'{before,postedOn}')::date THEN RAISE EXCEPTION 'TUITION_COURSE_VOID_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;
 IF NEW.created_by=(s#>>'{before,personId}')::uuid AND NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) THEN RAISE EXCEPTION 'BENEFICIARY_REVIEW_FORBIDDEN' USING ERRCODE='23514';END IF;NEW.created_at=clock_timestamp();RETURN NEW;
END $$;
CREATE TRIGGER tuition_course_void_guard BEFORE INSERT ON public.payroll_tuition_course_voids FOR EACH ROW EXECUTE FUNCTION public.tuition_course_void_guard();
CREATE FUNCTION public.tuition_course_posting_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE j record;b record;s jsonb;BEGIN
 SELECT * INTO j FROM public.finance_journals WHERE academy_id=NEW.academy_id AND id=NEW.id;
 IF j.id IS NULL OR j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.period_id IS DISTINCT FROM(NEW.input#>>'{period,id}')::uuid OR j.period_version IS DISTINCT FROM(NEW.input#>>'{period,version}')::integer OR j.posted_on IS DISTINCT FROM(NEW.input->>'postedOn')::date OR j.purpose IS DISTINCT FROM 'activity' OR j.line_count<>2 THEN RAISE EXCEPTION 'TUITION_COURSE_POSTING_REQUIRED' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='payroll_tuition_course_accruals' THEN
  IF j.reverses_id IS NOT NULL OR j.description IS DISTINCT FROM 'Recorded course tuition gross accrual' OR j.reference IS DISTINCT FROM 'PAYROLL-TUITION_COURSE' OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=1 AND account_id=NEW.expense_account AND account_version=NEW.expense_version AND side='debit' AND amount_minor=NEW.amount_minor AND note='') OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=2 AND account_id=NEW.liability_account AND account_version=NEW.liability_version AND side='credit' AND amount_minor=NEW.amount_minor AND note='') THEN RAISE EXCEPTION 'TUITION_COURSE_POSTING_REQUIRED' USING ERRCODE='23514';END IF;
  IF public.tuition_course_accrual_source(NEW.input,NEW.id) IS DISTINCT FROM NEW.source_snapshot THEN RAISE EXCEPTION 'TUITION_COURSE_SOURCE_CHANGED' USING ERRCODE='23514';END IF;
 ELSE
  SELECT * INTO b FROM public.payroll_tuition_course_accruals WHERE academy_id=NEW.academy_id AND id=NEW.accrual_id;
  IF b.void_id IS DISTINCT FROM NEW.id OR j.reverses_id IS DISTINCT FROM b.id OR j.description IS DISTINCT FROM 'Correction of course tuition gross accrual' OR j.reference IS DISTINCT FROM 'PAYROLL-TUITION_COURSE-CORRECTION' OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=1 AND account_id=b.expense_account AND account_version=b.expense_version AND side='credit' AND amount_minor=b.amount_minor AND note='') OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=2 AND account_id=b.liability_account AND account_version=b.liability_version AND side='debit' AND amount_minor=b.amount_minor AND note='') THEN RAISE EXCEPTION 'TUITION_COURSE_VOID_POSTING_REQUIRED' USING ERRCODE='23514';END IF;
  s=public.tuition_course_void_source(NEW.accrual_id,j.period_id);IF s->'current' IS DISTINCT FROM NEW.source_snapshot->'current' OR(s->'before')-'voidId' IS DISTINCT FROM(NEW.source_snapshot->'before')-'voidId' THEN RAISE EXCEPTION 'TUITION_COURSE_VOID_SOURCE_CHANGED' USING ERRCODE='23514';END IF;
 END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER tuition_course_posting_complete AFTER INSERT ON public.payroll_tuition_course_accruals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.tuition_course_posting_complete();
CREATE CONSTRAINT TRIGGER tuition_course_void_posting_complete AFTER INSERT ON public.payroll_tuition_course_voids DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.tuition_course_posting_complete();
CREATE CONSTRAINT TRIGGER tuition_course_reviewed AFTER INSERT ON public.payroll_tuition_course_accruals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.reviewed_approval_complete();
CREATE CONSTRAINT TRIGGER tuition_course_void_reviewed AFTER INSERT ON public.payroll_tuition_course_voids DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.reviewed_approval_complete();
CREATE FUNCTION public.tuition_course_effect_required() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.status='applied' AND((NEW.action='work.tuition_course.record' AND NOT EXISTS(SELECT 1 FROM public.payroll_tuition_course_accruals WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id)) OR(NEW.action='work.tuition_course.void' AND NOT EXISTS(SELECT 1 FROM public.payroll_tuition_course_voids WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id))) THEN RAISE EXCEPTION 'TUITION_COURSE_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER tuition_course_effect_required AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.tuition_course_effect_required();
CREATE FUNCTION public.tuition_course_reversal_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.payroll_tuition_course_accruals WHERE academy_id=NEW.academy_id AND id=NEW.reverses_id) AND NOT EXISTS(SELECT 1 FROM public.payroll_tuition_course_voids v JOIN public.approval_requests p ON p.academy_id=v.academy_id AND p.id=v.approval_id WHERE v.academy_id=NEW.academy_id AND v.id=NEW.id AND v.accrual_id=NEW.reverses_id AND p.action='work.tuition_course.void' AND p.target_id=NEW.id AND p.payload=v.input AND NEW.approval_id=p.id) THEN RAISE EXCEPTION 'TUITION_COURSE_CORRECTION_WORKFLOW_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER tuition_course_reversal_guard BEFORE INSERT ON public.finance_journals FOR EACH ROW WHEN(NEW.reverses_id IS NOT NULL) EXECUTE FUNCTION public.tuition_course_reversal_guard();
CREATE FUNCTION public.tuition_course_approval_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE w record;b record;a record;s jsonb;ids uuid[];invoice_ref uuid;BEGIN
 IF NEW.action='work.tuition_course.record' THEN invoice_ref=(NEW.payload->>'invoiceId')::uuid;SELECT * INTO w FROM public.work_engagements WHERE academy_id=NEW.academy_id AND id=(NEW.payload#>>'{engagement,id}')::uuid;ids=ARRAY[(NEW.payload#>>'{expenseAccount,id}')::uuid,(NEW.payload#>>'{liabilityAccount,id}')::uuid];
 ELSE SELECT * INTO b FROM public.payroll_tuition_course_accruals WHERE academy_id=NEW.academy_id AND id=(NEW.payload->>'accrualId')::uuid;SELECT * INTO w FROM public.work_engagements WHERE academy_id=NEW.academy_id AND id=b.engagement_id;invoice_ref=b.invoice_id;ids=ARRAY[b.expense_account,b.liability_account];END IF;
 IF w.id IS NULL THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));RETURN NEW;END IF;
 s=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',w.person_id,'hubId',w.hub_id)),'workContext',jsonb_build_object('personId',w.person_id,'hubId',w.hub_id));NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','work-pay.view','scope',s));
 FOR a IN SELECT id,hub_id FROM public.finance_accounts WHERE academy_id=NEW.academy_id AND id=ANY(ids) LOOP s=CASE WHEN a.hub_id IS NULL THEN jsonb_build_object('all',true,'hubs','[]'::jsonb) ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(a.hub_id)) END;NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','accounts.view','scope',s),jsonb_build_object('capability','journals.view','scope',s));END LOOP;
 IF(SELECT count(*) FROM public.finance_accounts WHERE academy_id=NEW.academy_id AND id=ANY(ids))<>2 THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));END IF;
 SELECT x.id,x.hub_id,x.class_id,x.student_id INTO a FROM public.tuition_invoices x WHERE x.academy_id=NEW.academy_id AND x.id=invoice_ref;
 IF a.id IS NULL THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));ELSE
 s=jsonb_build_object('all',false,'hubs','[]'::jsonb,'classes',jsonb_build_array(jsonb_build_object('id',a.class_id,'hubId',a.hub_id)),'people',jsonb_build_array(jsonb_build_object('id',a.student_id,'hubId',a.hub_id)),'recordContext',jsonb_build_object('hubId',a.hub_id,'classId',a.class_id,'studentId',a.student_id));NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','invoices.view','scope',s));END IF;RETURN NEW;
 EXCEPTION WHEN invalid_text_representation THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));RETURN NEW;
END $$;
CREATE TRIGGER zz_tuition_course_approval_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action IN('work.tuition_course.record','work.tuition_course.void')) EXECUTE FUNCTION public.tuition_course_approval_privacy();
REVOKE ALL ON FUNCTION public.tuition_course_input_valid(jsonb),public.tuition_course_accrual_source(jsonb,uuid),public.tuition_course_void_source(uuid,uuid),public.tuition_course_record_guard(),public.tuition_course_void_guard(),public.tuition_course_posting_complete(),public.tuition_course_effect_required(),public.tuition_course_reversal_guard(),public.tuition_course_approval_privacy() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tuition_course_input_valid(jsonb),public.tuition_course_accrual_source(jsonb,uuid),public.tuition_course_void_source(uuid,uuid) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 104 $$;

